import com.svc.voice.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class PortBusinessTest{
 static int checks;
 static void req(int port,String method,String path,String body,int expected)throws Exception{byte[] b=body.getBytes(StandardCharsets.UTF_8);try(Socket s=new Socket("127.0.0.1",port)){s.setSoTimeout(3000);s.getOutputStream().write((method+" /api/v1"+path+" HTTP/1.1\r\nHost: localhost\r\nContent-Type: multipart/form-data; boundary=testBoundary\r\nContent-Length: "+b.length+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII));s.getOutputStream().write(b);String text=new String(s.getInputStream().readAllBytes(),StandardCharsets.UTF_8);if(!text.startsWith("HTTP/1.1 "+expected))throw new AssertionError(text);if(expected>=400&&!text.contains("\"code\":"+expected))throw new AssertionError(text);checks++;}}
 static String fields(String...f){String b="";for(int i=0;i<f.length;i+=2)b+="--testBoundary\r\nContent-Disposition: form-data; name=\""+f[i]+"\"\r\n\r\n"+f[i+1]+"\r\n";return b+"--testBoundary--\r\n";}
 public static void main(String[]a)throws Exception{LocalHttpApi api=new LocalHttpApi(new android.content.Context());try(ServerSocket pick=new ServerSocket(0)){int port=pick.getLocalPort();pick.close();try(LocalHttpWire w=new LocalHttpWire("127.0.0.1",port,new File(System.getProperty("java.io.tmpdir"),"port-business-wire"),api)){req(port,"GET","/roles",fields(),200);req(port,"PUT","/config",fields("threads","-2"),400);req(port,"PUT","/config",fields("npu","true","threads","2"),200);req(port,"POST","/roles/import",fields("name","../oops"),400);Busy.acquire("rt");req(port,"POST","/tasks",fields(),409);Busy.release("rt");req(port,"GET","/tasks/missing",fields(),404);req(port,"GET","/logs",fields(),200);req(port,"DELETE","/logs",fields(),200);}}finally{api.close();}System.out.println("PASS "+checks+" real loopback business HTTP checks");}
}
